(()=>{const prefix="https://xamidulline.github.io/cheshuya/";const preview="https://raw.githack.com/xamidulline/cheshuya/preview-theme-and-font/dist/";const update=()=>document.querySelectorAll('a[href]').forEach(a=>{if(a.href.startsWith(prefix)&&/\.html(?:[?#]|$)/.test(a.href))a.href=preview+a.href.slice(prefix.length)});update();new MutationObserver(update).observe(document.documentElement,{childList:true,subtree:true});})();